238	+import io.github.julianperge.modular_planters.logic.Problem;
239	+import io.github.julianperge.modular_planters.registry.MPBlocks;
240	+import java.util.List;
241	+import java.util.Map;
242	+import net.minecraft.core.BlockPos;
243	+import net.minecraft.gametest.framework.GameTestHelper;
244	+import net.minecraft.nbt.CompoundTag;
245	+import net.minecraft.network.chat.Component;
246	+import net.minecraft.world.item.ItemStack;
247	+import net.minecraft.world.item.Items;
248	+
249	+public final class JadeTests {
250	+    private JadeTests() {
251	+    }
252	+
253	+    public static void register(Map<String, TestCase> into) {
254	+        into.put("formed_core_shows_its_part_count", new TestCase(20, JadeTests::formedCoreShowsItsPartCount));
255	+        into.put("core_shows_its_problem_until_formed", new TestCase(20, JadeTests::coreShowsItsProblemUntilFormed));
256	+        into.put("planter_shows_status_and_growing_seeds", new TestCase(20, JadeTests::planterShowsStatusAndGrowingSeeds));
257	+        into.put("unformed_planter_shows_idle", new TestCase(20, JadeTests::unformedPlanterShowsIdle));
258	+        into.put("empty_server_data_shows_no_lines", new TestCase(20, JadeTests::emptyServerDataShowsNoLines));
259	+    }
260	+
261	+    private static void formedCoreShowsItsPartCount(GameTestHelper helper) {
262	+        Fixtures.Rig rig = Fixtures.rig(helper, 1);
263	+        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
264	+        helper.startSequence()
265	+                .thenWaitUntil(() -> helper.assertTrue(core.lastScan().formed(), "formed after the first scan"))
266	+                .thenExecute(() -> helper.assertValueEqual(JadeInfo.coreLines(JadeInfo.core(core)),
267	+                        List.of(Component.translatable("modular_planters.jade.formed",
268	+                                core.lastScan().partCount(), MPConfig.PART_CAP.get())), "lines"))
269	+                .thenSucceed();
270	+    }
271	+
272	+    private static void coreShowsItsProblemUntilFormed(GameTestHelper helper) {
273	+        Fixtures.Rig rig = Fixtures.rig(helper, 1);
274	+        CoreBlockEntity core = helper.getBlockEntity(rig.core(), CoreBlockEntity.class);
275	+        helper.startSequence()
276	+                .thenWaitUntil(() -> helper.assertTrue(core.lastScan().formed(), "formed before the break"))
277	+                .thenExecute(() -> helper.getLevel().destroyBlock(helper.absolutePos(rig.power()), false))
278	+                .thenWaitUntil(() -> helper.assertValueEqual(core.lastScan().problem(), Problem.MISSING_POWER, "problem"))
279	+                .thenExecute(() -> helper.assertValueEqual(JadeInfo.coreLines(JadeInfo.core(core)),
280	+                        List.of(Component.translatable("modular_planters.jade.not_formed",
281	+                                Component.translatable("modular_planters.problem.missing_power"))), "lines"))
282	+                .thenSucceed();
283	+    }
284	+
285	+    private static void planterShowsStatusAndGrowingSeeds(GameTestHelper helper) {
286	+        Fixtures.Rig rig = Fixtures.rig(helper, 1);
287	+        PlanterBlockEntity planter = PlanterTests.planter(helper, rig, 0);
288	+        Fixtures.plant(planter, 64, 32, 0);
289	+        helper.startSequence()
290	+                .thenWaitUntil(() -> helper.assertValueEqual(planter.status(), PlanterStatus.SHORT_ON_SOIL, "status"))
291	+                .thenExecute(() -> helper.assertValueEqual(JadeInfo.planterLines(JadeInfo.planter(planter)), List.of(
292	+                        Component.translatable("modular_planters.status.short_on_soil"),
293	+                        Component.translatable("modular_planters.jade.growing", 32, 64)), "lines"))
294	+                .thenSucceed();
295	+    }
296	+
297	+    private static void unformedPlanterShowsIdle(GameTestHelper helper) {
298	+        BlockPos pos = new BlockPos(1, 1, 1);
299	+        helper.setBlock(pos, MPBlocks.PLANTER.get());
300	+        PlanterBlockEntity planter = helper.getBlockEntity(pos, PlanterBlockEntity.class);
301	+        planter.seeds().add(new ItemStack(Items.WHEAT_SEEDS), 10);
302	+        helper.assertValueEqual(JadeInfo.planterLines(JadeInfo.planter(planter)), List.of(
303	+                Component.translatable("modular_planters.status.idle"),
304	+                Component.translatable("modular_planters.jade.growing", 0, 10)), "lines");
305	+        helper.succeed();
306	+    }
307	+
308	+    private static void emptyServerDataShowsNoLines(GameTestHelper helper) {
309	+        helper.assertValueEqual(JadeInfo.coreLines(new CompoundTag()), List.of(), "core");
310	+        helper.assertValueEqual(JadeInfo.planterLines(new CompoundTag()), List.of(), "planter");
311	+        helper.succeed();
312	+    }
313	+}
