346	+package io.github.julianperge.modular_planters.jade;
347	+
348	+import io.github.julianperge.modular_planters.ModularPlanters;
349	+import io.github.julianperge.modular_planters.blockentity.CoreBlockEntity;
350	+import net.minecraft.nbt.CompoundTag;
351	+import net.minecraft.resources.Identifier;
352	+import snownee.jade.api.BlockAccessor;
353	+import snownee.jade.api.IBlockComponentProvider;
