355	+import snownee.jade.api.ITooltip;
356	+import snownee.jade.api.config.IPluginConfig;
357	+
358	+public enum CoreProvider implements IServerDataProvider<BlockAccessor>, IBlockComponentProvider {
359	+    INSTANCE;
360	+
361	+    private static final Identifier ID = Identifier.fromNamespaceAndPath(ModularPlanters.MOD_ID, "core");
362	+
363	+    @Override
364	+    public void appendServerData(CompoundTag data, BlockAccessor accessor) {
365	+        if (accessor.getBlockEntity() instanceof CoreBlockEntity blockEntity) {
366	+            data.merge(JadeInfo.core(blockEntity));
367	+        }
368	+    }
369	+
370	+    @Override
371	+    public void appendTooltip(ITooltip tooltip, BlockAccessor accessor, IPluginConfig config) {
372	+        JadeInfo.coreLines(accessor.getServerData()).forEach(tooltip::add);
373	+    }
374	+
375	+    @Override
376	+    public Identifier getUid() {
377	+        return ID;
378	+    }
379	+}
380	diff --git a/src/main/java/io/github/julianperge/modular_planters/jade/JadeInfo.java b/src/main/java/io/github/julianperge/modular_planters/jade/JadeInfo.java
