385	@@ -0,0 +1,53 @@
386	+package io.github.julianperge.modular_planters.jade;
387	+
388	+import io.github.julianperge.modular_planters.MPConfig;
389	+import io.github.julianperge.modular_planters.blockentity.CoreBlockEntity;
390	+import io.github.julianperge.modular_planters.blockentity.PlanterBlockEntity;
391	+import java.util.List;
392	+import java.util.Locale;
393	+import net.minecraft.nbt.CompoundTag;
394	+import net.minecraft.network.chat.Component;
395	+
396	+// This class imports nothing from Jade, so the mod works without it and the GameTests cover the lines.
397	+public final class JadeInfo {
398	+    private JadeInfo() {
399	+    }
400	+
401	+    public static CompoundTag core(CoreBlockEntity core) {
402	+        CompoundTag data = new CompoundTag();
403	+        data.putBoolean("formed", core.lastScan().formed());
404	+        data.putInt("parts", core.lastScan().partCount());
405	+        data.putInt("cap", MPConfig.PART_CAP.get());
406	+        data.putString("problem", core.lastScan().problem().name());
407	+        return data;
408	+    }
409	+
410	+    public static List<Component> coreLines(CompoundTag data) {
411	+        if (data.getBoolean("formed").isEmpty()) {
412	+            return List.of();
413	+        }
414	+        if (data.getBooleanOr("formed", false)) {
415	+            return List.of(Component.translatable("modular_planters.jade.formed",
416	+                    data.getIntOr("parts", 0), data.getIntOr("cap", 0)));
417	+        }
418	+        return List.of(Component.translatable("modular_planters.jade.not_formed",
419	+                Component.translatable("modular_planters.problem." + data.getStringOr("problem", "").toLowerCase(Locale.ROOT))));
420	+    }
421	+
422	+    public static CompoundTag planter(PlanterBlockEntity planter) {
423	+        CompoundTag data = new CompoundTag();
424	+        data.putString("status", planter.status().name());
425	+        data.putInt("growing", planter.growing());
426	+        data.putInt("seeds", planter.seeds().size());
427	+        return data;
428	+    }
429	+
430	+    public static List<Component> planterLines(CompoundTag data) {
431	+        if (data.getString("status").isEmpty()) {
432	+            return List.of();
433	+        }
434	+        return List.of(
435	+                Component.translatable("modular_planters.status." + data.getStringOr("status", "").toLowerCase(Locale.ROOT)),
436	+                Component.translatable("modular_planters.jade.growing", data.getIntOr("growing", 0), data.getIntOr("seeds", 0)));
