511	diff --git a/src/test/java/io/github/julianperge/modular_planters/wiki/WikiStructureTest.java b/src/test/java/io/github/julianperge/modular_planters/wiki/WikiStructureTest.java
512	new file mode 100644
513	index 0000000..a0a9781
514	--- /dev/null
515	+++ b/src/test/java/io/github/julianperge/modular_planters/wiki/WikiStructureTest.java
516	@@ -0,0 +1,173 @@
517	+package io.github.julianperge.modular_planters.wiki;
518	+
519	+import com.google.gson.JsonElement;
520	+import com.google.gson.JsonObject;
521	+import com.google.gson.JsonParser;
522	+import org.junit.jupiter.api.Test;
523	+
524	+import java.io.IOException;
525	+import java.nio.file.Files;
526	+import java.nio.file.Path;
527	+import java.util.ArrayList;
528	+import java.util.List;
529	+import java.util.Map;
530	+import java.util.Set;
531	+import java.util.TreeSet;
532	+import java.util.regex.Matcher;
533	+import java.util.regex.Pattern;
534	+import java.util.stream.Stream;
535	+
536	+import static org.junit.jupiter.api.Assertions.assertEquals;
537	+import static org.junit.jupiter.api.Assertions.assertTrue;
538	+
539	+class WikiStructureTest {
540	+    private static final String MOD_ID = "modular_planters";
541	+    private static final Path WIKI = Path.of("wiki");
542	+    private static final List<Path> PAGE_ROOTS = List.of(WIKI.resolve("docs"), WIKI.resolve("content"));
543	+    private static final Path RECIPES = Path.of("src/generated/resources/data/modular_planters/recipe");
544	+    static final Map<String, String> SHOWN_FOR_TAG = Map.of(
545	+            "#c:glass_blocks", "minecraft:glass",
546	+            "#ae2:interface", "ae2:interface",
547	+            "#c:gems/fluix", "ae2:fluix_crystal");
548	+    private static final Pattern CRAFTING_RECIPE = Pattern.compile(
549	+            "<CraftingRecipe\\s+slots=\\{\\[(.*?)\\]\\}\\s+result=\"([^\"]+)\"", Pattern.DOTALL);
550	+    private static final Pattern QUOTED = Pattern.compile("'([^']*)'");
551	+    private static final Pattern MOD_ASSET = Pattern.compile("<ModAsset\\s+location=\"([^\"]+)\"");
552	+
553	+    @Test
554	+    void wikiIdIsTheModId() throws IOException {
555	+        JsonObject json = readJson(WIKI.resolve("sinytra-wiki.json"));
556	+        assertEquals(MOD_ID, json.get("id").getAsString());
557	+    }
558	+
559	+    @Test
560	+    void theBookHasItsFolders() {
561	+        PAGE_ROOTS.forEach(WikiStructureTest::assertRootExists);
562	+        assertTrue(Files.isRegularFile(WIKI.resolve("docs/overview.mdx")), "wiki/docs/overview.mdx must exist");
563	+    }
564	+
565	+    @Test
566	+    void everyPageHasATitle() throws IOException {
567	+        for (Path page : pages(PAGE_ROOTS)) {
568	+            List<String> front = frontmatter(page);
569	+            assertTrue(front.stream().anyMatch(line -> line.startsWith("title:")), page + " has no title");
570	+            if (page.startsWith(WIKI.resolve("content"))) {
571	+                String name = page.getFileName().toString().replaceFirst("\\.mdx$", "");
572	+                assertTrue(front.contains("id: " + MOD_ID + ":" + name), page + " needs id: " + MOD_ID + ":" + name);
573	+                assertTrue(front.contains("type: block"), page + " needs type: block");
574	+            }
575	+        }
576	+    }
577	+
578	+    @Test
579	+    void metaFilesListEveryPageAndNothingElse() throws IOException {
580	+        for (Path root : PAGE_ROOTS) {
581	+            for (Path folder : folders(root)) {
582	+                Set<String> expected = new TreeSet<>();
583	+                try (Stream<Path> children = Files.list(folder)) {
584	+                    for (Path child : (Iterable<Path>) children::iterator) {
585	+                        String name = child.getFileName().toString();
586	+                        if (Files.isDirectory(child) || name.endsWith(".mdx")) {
587	+                            expected.add(name);
588	+                        }
589	+                    }
590	+                }
591	+                Set<String> actual = new TreeSet<>(readJson(folder.resolve("_meta.json")).keySet());
592	+                assertEquals(expected, actual, folder.resolve("_meta.json") + " keys");
593	+            }
594	+        }
595	+    }
596	+
597	+    @Test
598	+    void everyModAssetExists() throws IOException {
599	+        for (Path page : pages(PAGE_ROOTS)) {
600	+            Matcher matcher = MOD_ASSET.matcher(Files.readString(page));
601	+            while (matcher.find()) {
602	+                String[] location = matcher.group(1).split(":", 2);
603	+                assertEquals(2, location.length, page + " has a ModAsset location without a namespace: " + matcher.group(1));
604	+                Path image = WIKI.resolve("assets").resolve(location[0]).resolve(location[1] + ".png");
605	+                assertTrue(Files.isRegularFile(image), page + " references missing " + image);
606	+            }
607	+        }
608	+    }
609	+
610	+    @Test
611	+    void blockPagesMatchTheirRecipes() throws IOException {
612	+        List<Path> recipes;
613	+        try (Stream<Path> list = Files.list(RECIPES)) {
614	+            recipes = list.filter(p -> p.getFileName().toString().endsWith(".json")).sorted().toList();
615	+        }
616	+        assertEquals(7, recipes.size(), "recipe count");
617	+        for (Path recipe : recipes) {
618	+            String name = recipe.getFileName().toString().replaceFirst("\\.json$", "");
619	+            JsonObject json = readJson(recipe);
620	+            Path page = WIKI.resolve("content").resolve(name + ".mdx");
621	+            assertTrue(Files.isRegularFile(page), page + " does not exist");
622	+
623	+            Matcher matcher = CRAFTING_RECIPE.matcher(Files.readString(page));
624	+            assertTrue(matcher.find(), page + " has no <CraftingRecipe>");
625	+            String slotsText = matcher.group(1);
626	+            String result = matcher.group(2);
627	+            assertTrue(!matcher.find(), page + " has more than one <CraftingRecipe>");
628	+            assertEquals(json.getAsJsonObject("result").get("id").getAsString(), result, page + " result");
629	+
630	+            JsonObject key = json.getAsJsonObject("key");
631	+            List<String> expected = new ArrayList<>();
632	+            for (JsonElement row : json.getAsJsonArray("pattern")) {
633	+                for (char c : row.getAsString().toCharArray()) {
634	+                    expected.add(c == ' ' ? "" : shown(key.get(String.valueOf(c)).getAsString()));
635	+                }
636	+            }
637	+            List<String> actual = new ArrayList<>();
638	+            Matcher quoted = QUOTED.matcher(slotsText);
639	+            while (quoted.find()) {
640	+                actual.add(quoted.group(1));
641	+            }
642	+            assertEquals(9, actual.size(), page + " slot count");
643	+            assertEquals(expected, actual, page + " slots");
644	+        }
645	+    }
646	+
647	+    private static String shown(String item) {
648	+        if (!item.startsWith("#")) {
649	+            return item;
650	+        }
651	+        String shown = SHOWN_FOR_TAG.get(item);
652	+        assertTrue(shown != null, "tag " + item + " is missing from SHOWN_FOR_TAG");
653	+        return shown;
654	+    }
655	+
656	+    private static JsonObject readJson(Path file) throws IOException {
657	+        return JsonParser.parseString(Files.readString(file)).getAsJsonObject();
658	+    }
659	+
660	+    private static void assertRootExists(Path root) {
661	+        assertTrue(Files.isDirectory(root), root + " must exist and be a directory");
662	+    }
663	+
664	+    private static List<Path> folders(Path root) throws IOException {
665	+        assertRootExists(root);
666	+        try (Stream<Path> walk = Files.walk(root)) {
667	+            return walk.filter(Files::isDirectory).toList();
668	+        }
669	+    }
670	+
671	+    private static List<Path> pages(List<Path> roots) throws IOException {
672	+        List<Path> pages = new ArrayList<>();
673	+        for (Path root : roots) {
674	+            assertRootExists(root);
675	+            try (Stream<Path> walk = Files.walk(root)) {
676	+                walk.filter(p -> p.getFileName().toString().endsWith(".mdx")).forEach(pages::add);
677	+            }
678	+        }
679	+        return pages;
680	+    }
681	+
682	+    private static List<String> frontmatter(Path page) throws IOException {
683	+        List<String> lines = Files.readAllLines(page);
684	+        assertTrue(!lines.isEmpty() && lines.get(0).equals("---"), page + " must open with ---");
685	+        int end = lines.subList(1, lines.size()).indexOf("---");
686	+        assertTrue(end >= 0, page + " frontmatter is not closed");
687	+        return lines.subList(1, end + 1);
688	+    }
689	+}
